INSERT INTO `clinic` VALUES (1, 1, '呼吸内科门诊', '常见呼吸道感染、哮喘、慢性阻塞性肺疾病等疾病诊治。');
INSERT INTO `clinic` VALUES (2, 1, '心血管内科门诊', '高血压、冠心病、心律失常等诊治。');
INSERT INTO `clinic` VALUES (3, 1, '消化内科门诊', '胃炎、肠炎、消化道出血等诊治。');
INSERT INTO `clinic` VALUES (4, 1, '内分泌科门诊', '糖尿病、甲状腺疾病、肥胖等诊治。');
INSERT INTO `clinic` VALUES (5, 1, '神经内科门诊', '头痛、眩晕、失眠等神经系统常见疾病诊治。');
INSERT INTO `clinic` VALUES (6, 2, '普通外科门诊', '体表肿物、甲状腺、乳腺疾病及腹股沟疝等诊治。');
INSERT INTO `clinic` VALUES (7, 2, '骨科门诊', '骨折、脱位、运动损伤、颈肩腰腿痛等诊治。');
INSERT INTO `clinic` VALUES (8, 2, '泌尿外科门诊', '泌尿系统结石、感染等诊治。');
INSERT INTO `clinic` VALUES (9, 2, '烧伤整形外科门诊', '各类烧伤、创面处理及体表美容咨询。');
INSERT INTO `clinic` VALUES (10, 2, '肛肠外科门诊', '痔疮、肛裂等常见肛肠疾病诊治。');
INSERT INTO `clinic` VALUES (11, 3, '妇科门诊', '月经不调、妇科炎症、宫颈疾病等诊治。');
INSERT INTO `clinic` VALUES (12, 4, '儿科普通门诊', '儿童常见感冒、发烧、腹泻等疾病诊治。');
INSERT INTO `clinic` VALUES (13, 5, '中医内科门诊', '中医体质调理、慢性病的中药治疗。');
INSERT INTO `clinic` VALUES (14, 6, '耳鼻喉科门诊', '鼻炎、咽炎、扁桃体炎等疾病诊治。');
INSERT INTO `clinic` VALUES (15, 6, '眼科门诊', '近视、结膜炎、干眼症等诊治。');
INSERT INTO `department` VALUES (1, '内科', '负责内脏器官疾病诊断与非手术治疗，包括常见疾病和慢性病管理。');
INSERT INTO `department` VALUES (2, '外科', '负责外伤、肿瘤、感染等需手术治疗的疾病。');
INSERT INTO `department` VALUES (3, '妇产科', '负责女性生殖系统疾病及妊娠、分娩、产后健康管理。');
INSERT INTO `department` VALUES (4, '儿科', '负责儿童各阶段的健康与疾病诊治。');
INSERT INTO `department` VALUES (5, '中医科', '提供传统中医疗法，如针灸、推拿和中药调理。');
INSERT INTO `department` VALUES (6, '五官科', '耳鼻喉、眼科及口腔疾病的诊断与治疗。');
INSERT INTO `doctor` VALUES (1, 1, 1, '李文华', '副主任医师', '慢性咳嗽、哮喘、肺部感染', '资深呼吸内科专家，擅长呼吸系统疑难病诊治。');
INSERT INTO `doctor` VALUES (2, 2, 1, '张晓雯', '副主任医师', '戒烟咨询、肺功能检查解读', '专注于呼吸健康宣教和慢病管理。');
INSERT INTO `doctor` VALUES (3, 3, 1, '王建军', '主治医师', '常见感冒、支气管炎', '内科常见疾病诊疗经验丰富。');
INSERT INTO `doctor` VALUES (4, 4, 1, '赵梅', '主治医师', '呼吸系统慢病管理', '耐心细致，提供个性化慢病指导。');
INSERT INTO `doctor` VALUES (5, 5, 2, '刘强', '主任医师', '高血压、冠心病、心绞痛', '心血管领域权威，侧重高危患者管理。');
INSERT INTO `doctor` VALUES (6, 6, 2, '陈琳', '副主任医师', '心律失常及心电图判读', '精通心律失常的药物治疗。');
INSERT INTO `doctor` VALUES (7, 7, 2, '孙大为', '主治医师', '基础心血管疾病筛查', '擅长早期风险评估与生活方式干预。');
INSERT INTO `doctor` VALUES (8, 8, 3, '周明', '主任医师', '胃肠道常见疾病、幽门螺杆菌感染', '擅长消化系统常见病和多发病。');
INSERT INTO `doctor` VALUES (9, 9, 3, '吴芳', '主治医师', '功能性胃肠病、腹痛腹泻', '专治各种非器质性消化道不适。');
INSERT INTO `doctor` VALUES (10, 10, 4, '郑伟', '副主任医师', '糖尿病诊断与个体化治疗', '对代谢综合征有深入研究。');
INSERT INTO `doctor` VALUES (11, 11, 4, '钱丽', '主治医师', '甲状腺功能异常、内分泌失调', '关注年轻群体内分泌健康。');
INSERT INTO `doctor` VALUES (12, 12, 5, '冯涛', '主任医师', '头痛、偏头痛、睡眠障碍', '神经内科专家，尤其擅长慢性疼痛管理。');
INSERT INTO `doctor` VALUES (13, 13, 5, '顾悦', '主治医师', '眩晕症、焦虑状态', '提供神经心理咨询与治疗。');
INSERT INTO `doctor` VALUES (14, 14, 6, '魏东', '主任医师', '体表肿物、小创伤处理、疝气', '普通外科领域经验丰富，处理各种小手术。');
INSERT INTO `doctor` VALUES (15, 15, 6, '徐海燕', '副主任医师', '甲状腺、乳腺疾病筛查', '侧重女性外科疾病的早期诊断。');
INSERT INTO `doctor` VALUES (16, 16, 6, '许磊', '主治医师', '基础外科疾病、换药及术后随访', '细致耐心，擅长创面护理。');
INSERT INTO `doctor` VALUES (17, 17, 7, '朱斌', '副主任医师', '运动损伤、关节疼痛、颈椎病', '擅长非手术治疗各类骨科疼痛。');
INSERT INTO `doctor` VALUES (18, 18, 7, '秦雨', '主治医师', '软组织损伤、骨折复位后随诊', '专注于急性损伤和康复指导。');
INSERT INTO `doctor` VALUES (19, 19, 8, '曹阳', '主任医师', '泌尿系统感染、前列腺疾病', '泌尿生殖系统常见疾病诊治专家。');
